# Per-column/row z-score scan inside each 2-D tensor to find a single-column edit
import torch, numpy as np
cands = []
for L in range(24):
    for kind in ['mlp.gate_proj','mlp.up_proj','mlp.down_proj']:
        n = f'model.language_model.layers.{L}.{kind}.weight'
        W = load_original(n).float()
        col = W.norm(dim=0); row = W.norm(dim=1)
        for name, v in [('col', col), ('row', row)]:
            z = (v - v.mean()) / (v.std() + 1e-9)
            i = int(z.abs().argmax())
            if abs(z[i]) > 4:
                cands.append((float(abs(z[i])), n, name, i, float(v[i]), float(v.mean())))
